  "contradictory_card_ids": [],
  "decision_summary": "All transferred molecules with numeric absolute bioavailability measurements are at or above 20%, mostly 26-100%, supporting high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "Some qualitative records describe low or poor bioavailability for atazanavir, metoprolol, and vorinostat, but numeric absolute measurements in ordinary conditions consistently exceed 20%; these qualitative labels were discounted.",
    "Labetalol values are near the threshold (20-44%), adding minor uncertainty, but mean values remain at or above 20%."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C50", "C41", "C42"],
  "revision_action": "initial",
  "supportive_card_ids": ["C50", "C41", "C42"]
}

